//! Integration tests for the crate generated by `rust_runfile_library`.
//!
//! `bazel test` runs these in the test sandbox. `manifest_only` re-runs the
//! `manifest_only_child` test in a child process that can find its runfiles
//! only through `RUNFILES_MANIFEST_FILE`.

use std::path::{Path, PathBuf};
use std::process::Command;

use runfile::{Error, FileSet};
use test_resources as res;

fn read(path: impl AsRef<Path>) -> String {
    let path = path.as_ref();
    std::fs::read_to_string(path)
        .unwrap_or_else(|err| panic!("cannot read {}: {err}", path.display()))
        .trim()
        .to_owned()
}

fn rel_paths(set: &FileSet) -> Vec<&'static str> {
    set.rel_paths().collect()
}

/// Runs `command` and returns its trimmed stdout, failing on a non-zero exit.
fn run(mut command: Command) -> String {
    let output = command.output().expect("cannot start child process");
    assert!(
        output.status.success(),
        "child failed with {}\nstderr:\n{}",
        output.status,
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8(output.stdout).unwrap().trim().to_owned()
}

#[test]
fn single_file() {
    let file = res::SINGLE_FILE.resolve().unwrap();
    assert_eq!(read(file.path()), "dummy content");
    assert_eq!(file.rlocation_path(), "_main/data/dummy.txt");
    assert_eq!(res::SINGLE_FILE.rlocation_path(), "_main/data/dummy.txt");
    assert!(file.path().is_absolute(), "{}", file.path().display());
}

#[test]
fn executable_command_propagates_runfiles_env() {
    for spec in [res::EXECUTABLE_FILE, res::EXPLICIT_EXECUTABLE] {
        let helper = spec.resolve().unwrap();
        let command = helper.command();
        let keys: Vec<_> = command
            .get_envs()
            .map(|(k, _)| k.to_string_lossy().into_owned())
            .collect();
        assert!(
            keys.iter()
                .any(|k| k == "RUNFILES_DIR" || k == "RUNFILES_MANIFEST_FILE"),
            "command sets no runfiles variable: {keys:?}"
        );
        assert_eq!(run(command), "helper data content");
    }
}

#[test]
fn executable_without_runfiles_env_fails() {
    // The helper is not self-contained: without the propagated variables it
    // has no way to find data/helper_data.txt. This shows that the previous
    // test depends on `command()` setting them.
    // Run a copy outside the runfiles tree, so that the helper cannot find
    // `<helper>.runfiles` next to itself either.
    let helper = res::EXECUTABLE_FILE.must_resolve();
    let copy = PathBuf::from(std::env::var_os("TEST_TMPDIR").unwrap()).join("helper_copy");
    std::fs::copy(helper.path(), &copy).unwrap();
    let mut command = Command::new(&copy);
    for key in [
        "RUNFILES_DIR",
        "RUNFILES_MANIFEST_FILE",
        "JAVA_RUNFILES",
        "TEST_SRCDIR",
    ] {
        command.env_remove(key);
    }
    let output = command.output().unwrap();
    assert!(!output.status.success(), "helper unexpectedly succeeded");
}

#[test]
fn external_file() {
    let file = res::EXTERNAL_FILE.resolve().unwrap();
    assert!(read(file.path()).contains("name = \"rules_rust\""));
    assert!(
        file.rlocation_path().starts_with("rules_rust"),
        "{}",
        file.rlocation_path()
    );
}

#[test]
fn group_data() {
    let set = res::GROUP_DATA.resolve().unwrap();
    assert_eq!(rel_paths(&set), ["file1.txt", "file2.txt"]);
    assert_eq!(read(set.file("file1.txt").unwrap()), "content of file 1");
    assert_eq!(read(set.must_file("file2.txt")), "content of file 2");
    assert!(matches!(
        set.file("non-existent.txt"),
        Err(Error::NotInFileSet { .. })
    ));
}

#[test]
fn group_data_default_base() {
    let set = res::GROUP_DATA_DEFAULT.resolve().unwrap();
    assert_eq!(
        rel_paths(&set),
        ["data/collection/file1.txt", "data/collection/file2.txt"]
    );
    assert_eq!(
        read(set.file("data/collection/file1.txt").unwrap()),
        "content of file 1"
    );
}

#[test]
fn directory() {
    for spec in [res::DIR_DATA, res::WRAPPED_DIR, res::STRICT_DIR] {
        let dir = spec.resolve().unwrap();
        assert!(dir.path().is_dir(), "{}", dir.path().display());
        assert_eq!(read(dir.child("file1.txt")), "file1 content");
        assert_eq!(read(dir.child("file2.txt")), "file2 content");
    }
}

#[test]
fn mixed_group() {
    let set = res::MIXED_GROUP.resolve().unwrap();
    assert_eq!(rel_paths(&set), ["data/dummy.txt", "dir_data"]);
    let dir = set.file("dir_data").unwrap().path();
    assert!(dir.is_dir(), "{}", dir.display());
    assert_eq!(read(dir.join("file1.txt")), "file1 content");
}

#[test]
fn generated_file() {
    assert_eq!(read(res::GEN_DATA.must_resolve()), "generated");
}

#[test]
fn distant_group() {
    // The default base is the library's package, so the external file is
    // left out.
    let set = res::DISTANT_GROUP.resolve().unwrap();
    assert_eq!(rel_paths(&set), ["data/dummy.txt"]);
    assert_eq!(read(set.file("data/dummy.txt").unwrap()), "dummy content");

    let filtered = res::DISTANT_GROUP_FILTERED.resolve().unwrap();
    assert_eq!(rel_paths(&filtered), ["dummy.txt"]);

    let unfiltered = res::DISTANT_GROUP_UNFILTERED.resolve().unwrap();
    assert_eq!(
        rel_paths(&unfiltered),
        ["_main/data/dummy.txt", "rules_rust+/MODULE.bazel"]
    );
    assert!(read(unfiltered.file("rules_rust+/MODULE.bazel").unwrap()).contains("rules_rust"));
}

#[test]
fn mock_repo_group() {
    let set = res::MOCK_REPO_GROUP.resolve().unwrap();
    assert_eq!(rel_paths(&set), ["file1.txt", "file2.txt"]);
    assert_eq!(read(set.file("file1.txt").unwrap()), "mock file 1");
    assert_eq!(read(set.file("file2.txt").unwrap()), "mock file 2");
}

#[test]
fn sub_groups() {
    for spec in [
        res::SUB_GROUP_PACKAGE_RELATIVE,
        res::SUB_GROUP_REPO_RELATIVE,
    ] {
        let set = spec.resolve().unwrap();
        assert_eq!(rel_paths(&set), ["file1.txt", "file2.txt"]);
        assert_eq!(read(set.file("file1.txt").unwrap()), "sub file 1");
    }
}

#[test]
fn explicit_types() {
    assert_eq!(read(res::STRICT_FILE.must_resolve()), "dummy content");

    let strict = res::STRICT_FILE_SET.resolve().unwrap();
    assert_eq!(rel_paths(&strict), ["file1.txt", "file2.txt"]);

    let forced = res::FORCED_FILE_SET.resolve().unwrap();
    assert_eq!(rel_paths(&forced), ["data/dummy.txt"]);
    assert_eq!(
        read(forced.file("data/dummy.txt").unwrap()),
        "dummy content"
    );
}

#[test]
fn common_dir_file_set() {
    let set = res::COMMON_DIR_FILE_SET.resolve().unwrap();
    assert_eq!(rel_paths(&set), ["file1.txt", "file2.txt"]);
    assert_eq!(read(set.file("file1.txt").unwrap()), "content of file 1");
}

#[test]
fn duplicate_targets() {
    let stripped = res::DUPLICATE_TARGET1.resolve().unwrap();
    assert_eq!(rel_paths(&stripped), ["file1.txt", "file2.txt"]);

    let full = res::DUPLICATE_TARGET2.resolve().unwrap();
    assert_eq!(
        rel_paths(&full),
        [
            "_main/data/collection/file1.txt",
            "_main/data/collection/file2.txt"
        ]
    );
}

#[test]
fn mixed_file_set() {
    let set = res::MIXED_FILE_SET.resolve().unwrap();
    assert_eq!(
        rel_paths(&set),
        [
            "data/collection/file1.txt",
            "data/collection/file2.txt",
            "subdir/sub_data/file1.txt",
            "subdir/sub_data/file2.txt",
        ]
    );
    assert_eq!(
        read(set.file("data/collection/file1.txt").unwrap()),
        "content of file 1"
    );
    assert_eq!(
        read(set.file("subdir/sub_data/file1.txt").unwrap()),
        "sub file 1"
    );
}

/// Set in the child process started by `manifest_only`.
const MANIFEST_ONLY_CHILD: &str = "RUNFILE_TEST_MANIFEST_ONLY_CHILD";

#[test]
fn manifest_only() {
    let runfiles_dir = std::env::var_os("RUNFILES_DIR")
        .or_else(|| std::env::var_os("TEST_SRCDIR"))
        .map(PathBuf::from)
        .expect("bazel test sets RUNFILES_DIR or TEST_SRCDIR");
    let manifest = find_manifest(&runfiles_dir);

    let mut command = Command::new(std::env::current_exe().unwrap());
    command
        .args(["--exact", "manifest_only_child", "--ignored", "--nocapture"])
        .env(MANIFEST_ONLY_CHILD, "1")
        .env("RUNFILES_MANIFEST_FILE", &manifest)
        .env_remove("RUNFILES_DIR")
        .env_remove("JAVA_RUNFILES")
        .env_remove("TEST_SRCDIR");
    let output = run(command);
    assert!(output.contains("1 passed"), "{output}");
}

/// Returns the runfiles manifest Bazel wrote for this test.
///
/// The test sandbox does not always contain it (Bazel 9 leaves it out), but
/// it is next to the test binary in the output tree.
fn find_manifest(runfiles_dir: &Path) -> PathBuf {
    let next_to_binary = std::env::current_exe().ok().map(|exe| {
        let mut name = exe.file_name().unwrap().to_owned();
        name.push(".runfiles_manifest");
        exe.with_file_name(name)
    });
    let candidates = [
        std::env::var_os("RUNFILES_MANIFEST_FILE")
            .filter(|v| !v.is_empty())
            .map(PathBuf::from),
        Some(runfiles_dir.join("MANIFEST")),
        Some(runfiles_dir.with_extension("runfiles_manifest")),
        next_to_binary,
    ];
    let candidates: Vec<PathBuf> = candidates.into_iter().flatten().collect();
    candidates
        .iter()
        .find(|m| m.is_file())
        .unwrap_or_else(|| panic!("no runfiles manifest at any of {candidates:?}"))
        .clone()
}

/// Resolves runfiles with only `RUNFILES_MANIFEST_FILE` set. Run by
/// `manifest_only`; ignored otherwise.
#[test]
#[ignore = "run by manifest_only"]
fn manifest_only_child() {
    assert!(
        std::env::var_os(MANIFEST_ONLY_CHILD).is_some(),
        "run this through manifest_only"
    );
    assert!(std::env::var_os("RUNFILES_DIR").is_none());

    // Manifest entries point at the files themselves, not into the
    // runfiles tree.
    let file = res::SINGLE_FILE.resolve().unwrap();
    assert_eq!(read(file.path()), "dummy content");
    assert!(
        !file.path().to_string_lossy().contains(".runfiles/"),
        "resolved through the runfiles tree: {}",
        file.path().display()
    );

    let set = res::MOCK_REPO_GROUP.resolve().unwrap();
    assert_eq!(read(set.file("file2.txt").unwrap()), "mock file 2");

    let dir = res::DIR_DATA.resolve().unwrap();
    assert_eq!(read(dir.child("file1.txt")), "file1 content");

    // The child of this child also gets only the manifest.
    let command = res::EXECUTABLE_FILE.must_resolve().command();
    let env: Vec<_> = command
        .get_envs()
        .map(|(k, _)| k.to_string_lossy().into_owned())
        .collect();
    assert_eq!(env, ["RUNFILES_MANIFEST_FILE"]);
    assert_eq!(run(command), "helper data content");
}
